function rnd(s){return()=>{s=(s*16807)%2147483647;return(s-1)/2147483646}}
const IM={};
const byT=t=>WORKS.find(w=>w.t===t);
WORKS.forEach(w=>{w.cols=[];for(let i=0;i<w.dm.length;i+=6)w.cols.push('#'+w.dm.slice(i,i+6))});
const PLACES=[];WORKS.forEach(w=>{let p=PLACES.find(p=>p.short===w.short);if(!p){p={short:w.short,country:w.country,lat:w.lat,lon:w.lon,works:[]};PLACES.push(p)}p.works.push(w)});
const placeOf=w=>PLACES.find(p=>p.short===w.short);
function dm(v,pos,neg){const a=Math.abs(v);let d=Math.floor(a),m=Math.round((a-d)*60);if(m===60){d++;m=0}return`${d}\u00b0${String(m).padStart(2,'0')}\u2032${v>=0?pos:neg}`}
const coordStr=(lat,lon)=>`${dm(lat,'N','S')} ${dm(lon,'E','O')}`;

// ---------------- recorrido ----------------
const ANCH=[W*.25,H*.55];           // donde queda el pin (y el cursor) en cada parada
const CC=[W*.655,H*.455];           // centro del carrusel
const OV={x:-80,y:2,z:1};
const ST=[
 {names:['Tantos \u00e1ngulos','Infimos'],tr:3.0,durs:[.9],h:540,z:6.2},
 {names:['Selva Inconsiente','Permeable','Huellas','Para\u00edso Vintage','Expansi\u00f3n Naranja','Arcoiris','Infinidad Acuatica','Navegar','Inmersos','Evoluci\u00f3n'],tr:1.2,durs:Array(9).fill(.5),last_hold:.3,h:450,z:3.5},
 {names:['Versiones que conviven'],side:1,tr:1.35,durs:[],hold:1.0,h:300,z:5.6},
 {names:['Pertenecer','Pausa Rutera'],tr:.9,durs:[.85],h:500,z:5.8},
 {names:['Ciudad Emblem\u00e1tica','Reino Funghi','Agua-rela','Esp\u00edritu','Flore-SER'],tr:.75,durs:[.75,.6,.45,.4],h:450,z:7.5},
 {names:['Romantizando','Creando cuentos'],tr:.75,durs:[.8],h:500,z:6.6},
 {names:['El viaje'],last:1,tr:.9,durs:[],h:500,z:6.0},
];
{let t=2.2;for(const st of ST){st.ta=t;st.arr=t+st.tr;st.T=[st.arr+.35];st.durs.forEach(d=>st.T.push(st.T[st.T.length-1]+d));
  const endS=st.T[st.T.length-1];st.step=[st.T[0],endS];
  if(st.side){st.dep=st.arr+st.hold;st.vis=[st.arr-.4,st.dep+.3]}
  else if(st.last){st.dep=99;st.vis=[st.arr-.4,99]}
  else{st.dep=endS+(st.last_hold??.55);st.vis=[st.arr-.4,st.dep+.35]}
  t=st.dep}}
const TM=ST[ST.length-1].arr+.15, TC=TM+.35, TCE=TC+1.15;  // mapa se va, lienzo, fin del lienzo
ST.forEach((s,i)=>{s.ws=s.names.map(byT);s.i=i});
function sOf(st,t){const T=st.T,n=st.ws.length;if(n<2)return 0;if(t<=T[0])return 0;
  for(let i=0;i<n-1;i++)if(t<T[i+1])return i+E.io(seg(t,T[i],T[i+1]));return n-1}
function focusOf(st,s){const a=st.ws[Math.floor(s)],b=st.ws[Math.min(st.ws.length-1,Math.ceil(s))],u=s-Math.floor(s);return{x:lerp(a.lon,b.lon,u),y:lerp(a.lat,b.lat,u)}}
function cam(t){
  if(t<=ST[0].ta)return{F:{...OV},z:1,A:[W/2,H/2]};
  for(let i=0;i<ST.length;i++){const st=ST[i];
    if(t<st.arr&&t>=st.ta){const prev=i?ST[i-1]:null;
      const F0=prev?focusOf(prev,prev.ws.length-1):OV,z0=prev?prev.z*1.1:1,A0=prev?ANCH:[W/2,H/2];
      const F1=focusOf(st,0),u=E.io(seg(t,st.ta,st.arr)),dist=Math.hypot(F1.x-F0.x,F1.y-F0.y);
      const dip=1-Math.min(.6,dist/55)*Math.sin(Math.PI*E.sine(seg(t,st.ta,st.arr)));
      return{F:{x:lerp(F0.x,F1.x,u),y:lerp(F0.y,F1.y,u)},z:Math.exp(lerp(Math.log(z0),Math.log(st.z),u))*dip,A:[lerp(A0[0],ANCH[0],u),lerp(A0[1],ANCH[1],u)]}}
    if(t>=st.arr&&t<(ST[i+1]?ST[i+1].ta:1e9)){
      return{F:focusOf(st,sOf(st,t)),z:st.z*lerp(1,1.1,E.sine(seg(t,st.arr,st.dep>50?st.arr+2:st.dep))),A:ANCH}}}
  return{F:{...OV},z:1,A:[W/2,H/2]};
}
const flat=(lon,lat,c)=>[c.A[0]+(lon-c.F.x)*K*c.z,c.A[1]-(lat-c.F.y)*K*c.z];
function globe(t){const u=E.io(seg(t,0,3.2));
  return{l0:lerp(-140,-80,u),p0:lerp(18,2,u),R:lerp(340,630,E.io(seg(t,1.7,3.3)))*lerp(.95,1,E.o(seg(t,0,1.0)))}}
function ortho(lon,lat,g){const l=(lon-g.l0)*D,f=lat*D,f0=g.p0*D,cf=Math.cos(f);
  const cc=Math.sin(f0)*Math.sin(f)+Math.cos(f0)*cf*Math.cos(l);
  return[W/2+g.R*cf*Math.sin(l),H/2-g.R*(Math.cos(f0)*Math.sin(f)-Math.sin(f0)*cf*Math.cos(l)),cc]}
const MU=t=>E.io(seg(t,2.7,4.5));    // globo -> mapa plano
function proj(lon,lat,g,c,mu){const o=ortho(lon,lat,g);if(mu<=0)return o;const f=flat(lon,lat,c);
  if(o[2]>0)return[lerp(o[0],f[0],mu),lerp(o[1],f[1],mu),lerp(o[2],1,mu)];return[f[0],f[1],seg(mu,.75,1)]}

// ---------------- helpers ----------------
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect?ctx.roundRect(x,y,w,h,r):ctx.rect(x,y,w,h)}
function photo(img,cx,cy,w,h,{a=1,kb=1,shadow=0}={}){
  if(a<=0||w<1||h<1)return;ctx.save();ctx.globalAlpha=a;
  if(shadow>0){ctx.shadowColor=`rgba(60,42,25,${.14*shadow})`;ctx.shadowBlur=36;ctx.shadowOffsetY=12;ctx.fillStyle=C.paper;ctx.fillRect(cx-w/2,cy-h/2,w,h);ctx.shadowColor='transparent'}
  rr(cx-w/2,cy-h/2,w,h,2);ctx.clip();
  const ia=img.width/img.height,ra=w/h;let sw,sh;if(ia>ra){sh=img.height/kb;sw=sh*ra}else{sw=img.width/kb;sh=sw/ra}
  ctx.drawImage(img,(img.width-sw)/2,(img.height-sh)/2,sw,sh,cx-w/2,cy-h/2,w,h);ctx.restore()}
function persp(img,cx,cy,w,h,th,a){
  if(a<=0)return;if(a<.999){pc.width=W;pc.height=H;const sv=ctx;ctx=pcx;persp(img,cx,cy,w,h,th,1);ctx=sv;ctx.save();ctx.globalAlpha=a;ctx.drawImage(pc,0,0);ctx.restore();return}
  if(Math.abs(th)<.002)return photo(img,cx,cy,w,h);
  const N=40,p=1800,ct=Math.cos(th),st=Math.sin(th);
  for(let k=0;k<N;k++){const u0=-w/2+k*w/N,u1=u0+w/N,um=(u0+u1)/2;const s0=p/(p+u0*st),s1=p/(p+u1*st),sm=p/(p+um*st);
    const x0=cx+u0*ct*s0,x1=cx+u1*ct*s1,hh=h*sm;ctx.drawImage(img,img.width*k/N,0,img.width/N,img.height,x0,cy-hh/2,Math.max(1,x1-x0+1.6),hh)}}
function text(s,x,y,font,color,a,align='left',ls=0){if(a<=0||!s)return;ctx.save();ctx.globalAlpha=a;ctx.font=font;ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='alphabetic';
  if(ls&&'letterSpacing' in ctx)ctx.letterSpacing=ls+'px';ctx.fillText(s,x,y);ctx.restore()}
const typed=(s,k)=>s.slice(0,Math.ceil(s.length*cl(k)));

// ---------------- globo + mapa ----------------
function drawMap(t,g,c,mu){
  const grA=seg(t,3.7,4.6)*(1-seg(t,TM,TM+.7));
  if(grA>0){ctx.strokeStyle=C.line;ctx.lineWidth=1;ctx.globalAlpha=grA*.75;ctx.beginPath();
    const step=c.z>4?2:c.z>2?5:10;
    for(let lon=-180;lon<=0;lon+=step){const x=flat(lon,0,c)[0];if(x>-2&&x<W+2){ctx.moveTo(x,0);ctx.lineTo(x,H)}}
    for(let lat=-80;lat<=80;lat+=step){const y=flat(0,lat,c)[1];if(y>-2&&y<H+2){ctx.moveTo(0,y);ctx.lineTo(W,y)}}
    ctx.stroke();ctx.globalAlpha=1}
  const oA=(1-seg(t,2.6,3.4))*seg(t,.1,.7);
  if(oA>0){ctx.strokeStyle=C.line;ctx.globalAlpha=oA;ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(W/2,H/2,g.R,0,7);ctx.stroke();ctx.globalAlpha=1}
  const gA=1-seg(t,3.9,4.8);
  if(gA>0){ctx.fillStyle=C.dot;const rb=Math.sqrt(g.R/420);
    for(let i=0;i<GDOTS.length;i+=2){const lon=GDOTS[i],lat=GDOTS[i+1];
      const ap=seg(t,.02+(90-lat)/180*.6,.35+(90-lat)/180*.6);if(ap<=0)continue;
      const p=proj(lon,lat,g,c,mu);if(p[2]<=0)continue;const x=p[0],y=p[1];if(x<-4||x>W+4||y<-4||y>H+4)continue;
      const a=(mu>0?p[2]:.25+.75*p[2])*ap*gA;if(a<.03)continue;const r=lerp(.9+.9*p[2],1.6,mu)*rb;
      ctx.globalAlpha=a;ctx.fillRect(x-r,y-r,r*2,r*2)}
    ctx.globalAlpha=1}
  const aA=seg(t,3.9,4.8)*(1-seg(t,TM+.1,TM+.8));
  if(aA>0){ctx.fillStyle=C.dot;ctx.globalAlpha=aA;const r=Math.min(3.2,1.05+.36*c.z);const kz=K*c.z;
    for(let i=0;i<ADOTS.length;i+=2){const x=c.A[0]+(ADOTS[i]-c.F.x)*kz,y=c.A[1]-(ADOTS[i+1]-c.F.y)*kz;
      if(x<-4||x>W+4||y<-4||y>H+4)continue;ctx.fillRect(x-r,y-r,r*2,r*2)}
    ctx.globalAlpha=1}
}
// fotos que se componen sobre el globo con sus propios puntos
// puntos que se oscurecen donde hay fotos
function drawHot(t,g,c,mu){const fade=1-seg(t,4.1,4.9);if(fade<=0)return;const rb=Math.sqrt(g.R/420);
  for(const h of HOT){const pl=PLACES[h.p];const k=E.s(seg(t,pl.ti+h.dl,pl.ti+h.dl+.5));if(k<=0)continue;
    const p=proj(h.lon,h.lat,g,c,mu);if(p[2]<=0)continue;const r=lerp(.9+.9*p[2],1.6,mu)*rb*lerp(1,1.35,k*h.w);
    ctx.globalAlpha=k*h.w*fade*(mu>0?p[2]:.35+.65*p[2]);ctx.fillStyle=C.ink;ctx.fillRect(p[0]-r,p[1]-r,r*2,r*2)}
  ctx.globalAlpha=1;
  // un c\u00edrculo latente al encenderse cada lugar
  for(const pl of PLACES){if(t<pl.ti)continue;const p=proj(pl.lon,pl.lat,g,c,mu);if(p[2]<=.05)continue;
    for(let k=0;k<2;k++){const ph=((t-pl.ti)*.6+k*.5)%1;ctx.globalAlpha=(1-ph)*.35*cl(p[2]*3)*fade*seg(t,pl.ti,pl.ti+.4);ctx.strokeStyle=C.ink;ctx.lineWidth=1;
      ctx.beginPath();ctx.arc(p[0],p[1],lerp(3,18,E.o(ph))*Math.sqrt(g.R/420),0,7);ctx.stroke()}}
  ctx.globalAlpha=1}
function drawRoute(){}
function drawPins(t,g,c,mu){const a0=seg(t,4.2,4.9)*(1-seg(t,TM,TM+.6));if(a0<=0)return;const F=cam(t).F;
  PLACES.forEach((pl,i)=>{const p=proj(pl.lon,pl.lat,g,c,mu);if(p[0]<-40||p[0]>W+40||p[1]<-40||p[1]>H+40)return;
    const v=pl.visit!==undefined&&t>=pl.visit;const near=Math.hypot(pl.lon-F.x,pl.lat-F.y)*K*c.z<30;
    for(let k=0;k<2;k++){const ph=((t*.55+i*.37+k*.5)%1);const R=lerp(5,near?34:20,E.o(ph));
      ctx.globalAlpha=a0*(1-ph)*(near?.5:.28);ctx.strokeStyle=C.ink;ctx.lineWidth=1;ctx.beginPath();ctx.arc(p[0],p[1],R,0,7);ctx.stroke()}
    ctx.globalAlpha=a0;ctx.fillStyle=C.ink;ctx.beginPath();ctx.arc(p[0],p[1],v?4.5:3.2,0,7);ctx.fill();
    if(!v){ctx.fillStyle=C.paper;ctx.beginPath();ctx.arc(p[0],p[1],1.6,0,7);ctx.fill()}});
  ctx.globalAlpha=1}
function cursorPos(t,c,g){const F=cam(t).F;const q=proj(F.x,F.y,g,c,MU(t));return{F,p:[q[0],q[1]]}}
function crossLines(t,c,g){const a=E.o(seg(t,1.0,1.8))*(1-seg(t,TM,TM+.5));if(a<=0)return;const{p}=cursorPos(t,c,g);const L=E.io(seg(t,1.0,2.1));
  ctx.save();ctx.strokeStyle=C.ink;ctx.globalAlpha=a*.38;ctx.lineWidth=1;ctx.beginPath();
  ctx.moveTo(p[0]-L*W,p[1]);ctx.lineTo(p[0]+L*W,p[1]);ctx.moveTo(p[0],p[1]-L*H);ctx.lineTo(p[0],p[1]+L*H);ctx.stroke();ctx.restore()}
function cursorTop(t,c,g){const a=E.o(seg(t,1.2,2.0))*(1-seg(t,TM,TM+.5));if(a<=0)return;const{F,p}=cursorPos(t,c,g);
  ctx.save();ctx.globalAlpha=a;ctx.fillStyle=C.ink;ctx.beginPath();ctx.arc(p[0],p[1],5,0,7);ctx.fill();
  ctx.strokeStyle=C.ink;ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(p[0],p[1],14,0,7);ctx.stroke();ctx.restore();
  const s=coordStr(F.y,F.x);ctx.save();ctx.font=`22px ${FM}`;const tw=ctx.measureText(s).width;const bx=p[0]-28-tw-28,by=p[1]+24;
  ctx.globalAlpha=a;ctx.fillStyle='rgba(250,248,244,.95)';ctx.fillRect(bx,by,tw+28,46);ctx.strokeStyle=C.line;ctx.lineWidth=1;ctx.strokeRect(bx+.5,by+.5,tw+27,45);
  ctx.fillStyle=C.ink;ctx.fillText(s,bx+14,by+31);ctx.restore();
  const L=labelAt(t);if(L){text(typed(L.country.toUpperCase(),L.k*1.6),p[0]-28,p[1]-62,`16px ${FM}`,C.muted,a*L.a,'right',2.5);
    text(typed(L.city,L.k),p[0]-28,p[1]-26,`40px ${FS}`,C.ink,a*L.a,'right')}}
function labelAt(t){for(const st of ST){if(t<st.arr-.45||t>st.dep+.35)continue;
    const n=st.ws.length;const s=sOf(st,t);const idx=Math.round(s);const pl=placeOf(st.ws[idx]);
    let first=idx;while(first>0&&st.ws[first-1].short===st.ws[idx].short)first--;
    const tc=first===0?st.arr-.45:(st.T[first-1]+st.T[first])/2;
    const k=E.o(seg(t,tc,tc+.55));const a=1-seg(t,st.dep,st.dep+.3);
    const nm=pl.short==='Obelisco'?'Buenos Aires':pl.short;
    return{city:nm,country:pl.country,k,a}}
  return null}

// ---------------- carrusel en cada parada ----------------
function stopVis(st,t){return Math.min(seg(t,st.vis[0],st.vis[0]+.6),1-seg(t,st.vis[1]-.55,st.vis[1]))}
function dimAt(t){let m=0;for(const st of ST){const v=E.s(stopVis(st,t))*(st.side?.18:.42);m=Math.max(m,v)}return m}
function drawStop(st,t){if(t<st.vis[0]||t>st.vis[1])return;const s=sOf(st,t);
  if(st.side){const w=st.ws[0];const h=420,ww=h*w.ar;const cx=CC[0]-30,cy=CC[1]-10;
    const kin=E.o(seg(t,st.vis[0],st.vis[0]+.7)),kout=E.io(seg(t,st.vis[1]-.55,st.vis[1]));
    photo(IM[w.f],cx+lerp(30,0,kin)-24*kout,cy,ww,h,{a:kin*(1-kout),kb:lerp(1,1.05,seg(t,st.vis[0],st.vis[1]))});
    caption(w,cx,cy+h/2+44,kin*(1-kout));return}
  // tira editorial: la foto central grande, las vecinas m\u00e1s chicas, siempre con aire entre ellas
  const H0=st.h,gap=36,n=st.ws.length;
  const sz=st.ws.map((w,i)=>{const ad=Math.abs(i-s);const k=lerp(1,.62,E.s(Math.min(ad,1)));return{h:H0*k,w:H0*k*w.ar}});
  const pos=[0];for(let i=1;i<n;i++)pos[i]=pos[i-1]+sz[i-1].w/2+gap+sz[i].w/2;
  const f=Math.floor(s),P=f>=n-1?pos[n-1]:lerp(pos[f],pos[f+1],s-f);
  st.ws.forEach((w,i)=>{const ad=Math.abs(i-s);const delay=Math.min(ad,3)*.08;
    const kin=E.o(seg(t,st.vis[0]+delay,st.vis[0]+delay+.7)),kout=E.io(seg(t,st.vis[1]-.6+delay*.5,st.vis[1]-.05));
    const cx=CC[0]+pos[i]-P+lerp(40,0,kin)-30*kout;const left=cx-sz[i].w/2;
    let a=kin*(1-kout)*(1-seg(ad,2.2,3))*lerp(1,.85,cl(ad))*seg(left,ANCH[0]+30,ANCH[0]+150)*(1-seg(cx+sz[i].w/2,W-10,W+120));
    photo(IM[w.f],cx,CC[1],sz[i].w,sz[i].h,{a,kb:lerp(1,1.04,seg(t,st.vis[0],st.vis[1]))})});
  st.ws.forEach((w,i)=>{const a=(1-Math.min(1,Math.abs(i-s)*2.2))*stopVis(st,t);if(a>0)caption(w,CC[0],CC[1]+H0/2+44,a)})}
function caption(w,x,y,a){if(a<=0)return;
  text(`N.\u00ba ${String(w.n).padStart(2,'0')} \u00b7 ${w.coords}`,x,y,`15px ${FM}`,C.muted,a,'center',.8);
  text(w.t,x,y+44,`38px ${FS}`,C.ink,a,'center')}

// ---------------- lienzo infinito y cierre ----------------
let CARDS=[],HOT=[];
function buildCanvas(){const r=rnd(7);const pool=WORKS;const viaje=byT('El viaje');
  for(let row=-4;row<=4;row++)for(let col=-6;col<=6;col++){const main=row===0&&col===0;
    const w=main?viaje:pool[(((row+4)*13+(col+6))*7+(row+4)*3)%pool.length];
    const h=main?240:lerp(160,230,r());
    CARDS.push({w,main,x:col*330+(main?0:(r()-.5)*60+(row%2?165:0)),y:row*310+(main?0:(r()-.5)*50),h,d:Math.hypot(col*330,row*310),j:r()})}
  const md=Math.max(...CARDS.map(c=>c.d));CARDS.forEach(c=>c.d/=md)}
function infinite(t){const t0=TC;if(t<t0||t>TCE)return;const H0=ST[ST.length-1].h;
  const zu=seg(t,t0,TCE);const z=Math.exp(lerp(Math.log(H0/240),Math.log(.6),E.o(zu)*.85+zu*.15));
  const mv=E.io(seg(t,t0,t0+1.1));const ox=(CC[0]-W/2)*(1-mv),oy=(CC[1]-H/2)*(1-mv);
  const cx=lerp(0,200,E.sine(zu)),cy=lerp(0,110,E.sine(zu));
  const fo=1-E.io(seg(t,TCE-.6,TCE));
  const order=[...CARDS].sort((a,b)=>a.main?1:b.main?-1:0);
  for(const cd of order){const at=t0+.05+cd.d*1.0+cd.j*.25;const k=cd.main?1:E.o(seg(t,at,at+.6));if(k<=0)continue;
    const sx=W/2+ox+(cd.x-cx)*z,sy=H/2+oy+(cd.y-cy)*z;const hh=cd.h*z,ww=hh*cd.w.ar;
    if(sx+ww/2<0||sx-ww/2>W||sy+hh/2<0||sy-hh/2>H)continue;
    photo(IM[cd.w.f],sx,sy,ww,hh,{a:k*fo})}}
